// WF-06 · Composición del ticket y saneado de PII.
//
// Dos responsabilidades:
//
//  1. CADENA DE CUSTODIA. El ticket debe permitir reconstruir la decisión
//     meses después, cuando nadie recuerde el incidente: qué se detectó, qué
//     dijo cada proveedor, qué puntuó el motor, qué se ejecutó y quién lo
//     aprobó.
//
//  2. SANEADO. El SOAR maneja PII de empleados y claves transitorias. Lo que
//     se escribe en un ticket sale del perímetro del SOC hacia una plataforma
//     que ve mucha más gente. Se recorta antes de escribir, no después.

const a = $input.first().json;
const t = a.triage ?? {};
const e = a.enrichment ?? {};

// Campos que nunca viajan al ticket: el log crudo puede contener credenciales
// en claro, rutas de usuario y contenido de ficheros.
function sanear(obj) {
  if (!obj || typeof obj !== 'object') return obj;
  const prohibidos = ['raw', 'full_log', 'rawBody', 'password', 'token', 'api_key', 'secret'];
  const salida = Array.isArray(obj) ? [] : {};
  for (const [k, v] of Object.entries(obj)) {
    if (prohibidos.includes(k)) continue;
    salida[k] = v && typeof v === 'object' ? sanear(v) : v;
  }
  return salida;
}

const severidad = { false_positive: 1, investigate: 2, critical: 3 }[t.verdict] ?? 2;

const resumenProveedores = Object.entries(e)
  .filter(([k]) => k !== '_meta')
  .map(([nombre, r]) => {
    if (!r.available) return `- ${nombre}: NO DISPONIBLE (${r.error})`;
    return `- ${nombre}: ${r.verdict}`;
  })
  .join('\n');

const acciones = (a.plan?.actions ?? [])
  .map((ac) => `- ${ac.action_type} sobre ${ac.target} vía ${ac.platform} (caduca ${ac.expires_at})`)
  .join('\n') || '- ninguna';

const descripcion = [
  `## Detección`,
  `Origen: ${a.source} · Regla ${a.rule?.id} — ${a.rule?.name} (nivel ${a.rule?.level})`,
  `Activo: ${a.asset?.host} (criticidad: ${a.asset?.criticality})`,
  a.identity?.user ? `Usuario: ${a.identity.user}` : null,
  ``,
  `## Veredicto`,
  `Puntuación: ${t.score}/100 → **${t.verdict}**`,
  t.caps?.length ? `Techos aplicados: ${t.caps.join(', ')}` : null,
  ``,
  `### Por qué`,
  ...(t.rationale ?? []).map((r) => `- ${r}`),
  ``,
  `## Inteligencia de amenazas`,
  resumenProveedores,
  e._meta?.partial ? `\n⚠️ Enriquecimiento PARCIAL. Caídos: ${e._meta.failed.join(', ')}` : null,
  ``,
  `## Contención`,
  acciones,
  a.aprobadoPor ? `\nAprobado por: ${a.aprobadoPor}` : null,
  a.plan?.skipped?.length ? `\nOmitida por: ${a.plan.skipped.join(', ')}` : null,
  ``,
  `---`,
  `alert_id: ${a.alert_id} · pesos v${t.weightsVersion} · latencia e2e ${a.timings?.e2eMs ?? '?'} ms`,
]
  .filter((l) => l !== null)
  .join('\n');

return [
  {
    json: {
      alert_id: a.alert_id,
      titulo: `[BlinkSec] ${a.rule?.name ?? 'Alerta'} — ${a.asset?.host ?? 'host desconocido'}`,
      descripcion,
      severidad,
      verdict: t.verdict,
      score: t.score,
      tags: [a.source, a.rule?.id, t.verdict, ...(a.rule?.mitre ?? [])].filter(Boolean),
      observables: [
        ...(a.artifacts?.ips ?? []).map((i) => ({ dataType: 'ip', data: i.value })),
        ...(a.artifacts?.hashes ?? []).map((h) => ({ dataType: 'hash', data: h.value })),
      ],
      alertaSaneada: sanear(a),
    },
  },
];
